#if TEST_BUILD
using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;
internal sealed partial class ControlWindow {
 internal async Task RunDailyPolishSmoke(string mode){try{
  if(mode=="empty-restart"){Require(library.Doc.Items.Count==0&&selected==null&&!preview.Enabled&&!desktop.Enabled&&!removeWallpaper.Enabled&&CurrentRun==null,"Empty catalog reappeared or autoplay");ClientShot(this,"empty-library-restart");Common.SaveNew(Path.Combine(Common.Root,"evidence/empty-restart-passed.json"),new{cards=0,autoReadded=false,autoPlayed=false});Close();return;}
  var initial=library.Doc.Items.ToArray();Require(initial.Length>=5,"Newest catalog not migrated");var hashes=initial.ToDictionary(x=>x.Id,x=>Common.Hash(x.SourcePath));var covers=initial.Where(x=>x.CoverPath!=null).ToDictionary(x=>x.Id,x=>Common.Hash(x.CoverPath));
  ClientShot(this,"daily-home-before");var builtin=library.Doc.Items.Single(x=>x.Id=="builtin-317495");SelectWallpaper(builtin);
  await StartMode("preview");await WaitOfflineState("preview");await Task.Delay(1500);
  int nameChanges=0,timeChanges=0;EventHandler n=(s,e)=>nameChanges++,t=(s,e)=>timeChanges++;activeName.TextChanged+=n;countdown.TextChanged+=t;
  for(int i=0;i<10;i++)PresentationTick();Require(nameChanges==0&&timeChanges<=1,"Repeated presentation tick rewrites stable status");int sameTicksName=nameChanges,sameTicksTime=timeChanges;
  await Task.Delay(3200);Require(nameChanges==0&&timeChanges<=6,"Live banner repeatedly erased/repainted");ClientShot(this,"stable-preview-home");Common.SaveNew(Path.Combine(Common.Root,"evidence/banner-update-check.json"),new{sameTicks=10,sameTicksNameChanges=sameTicksName,sameTicksTimeChanges=sameTicksTime,observedSeconds=3.2,nameChanges=nameChanges,timeChanges=timeChanges,playerPid=player.Pid,creation=player.Creation,singleSameNativeInstance=true,method="TextChanged events on actual live WinForms labels, plus UI capture",elapsedDisplay=countdown.Text});activeName.TextChanged-=n;countdown.TextChanged-=t;
  await StopManaged("daily-preview-stop");Require(Clean,"Preview stop");await StartMode("desktop");await WaitOfflineState("mounted");await Task.Delay(1500);ClientShot(this,"stable-desktop-home");
  int playingPid=player.Pid;long playingCreation=player.Creation;var inactive=library.Doc.Items.Single(x=>x.ResourceId=="28987");SelectWallpaper(inactive);await RemoveChosenWallpaper(false);Require(!library.Doc.Items.Contains(inactive)&&player.Pid==playingPid&&player.Creation==playingCreation&&PlayerRole=="alive","Inactive removal disturbed current desktop");Require(File.Exists(inactive.SourcePath)&&Common.Hash(inactive.SourcePath)==hashes[inactive.Id],"Inactive source deleted");
  SelectWallpaper(builtin);await RemoveChosenWallpaper(false);Require(Clean&&!library.Doc.Items.Contains(builtin)&&File.Exists(builtin.SourcePath),"Active removal did not clean before catalog removal");ClientShot(this,"removed-active-wallpaper");
  int countBefore=library.Doc.Items.Count;var failureTarget=library.Selected;SelectWallpaper(failureTarget);library.Error="Synthetic test-only catalog read error";await RemoveChosenWallpaper(false);Require(library.Doc.Items.Count==countBefore&&library.Doc.Items.Contains(failureTarget),"Read-error removal altered catalog");library.Error=null;
  foreach(var item in library.Doc.Items.ToArray()){SelectWallpaper(item);await RemoveChosenWallpaper(false);}
  Require(library.Doc.Items.Count==0&&selected==null&&!preview.Enabled&&!desktop.Enabled&&!removeWallpaper.Enabled,"Last-item removal empty state");ClientShot(this,"empty-library");
  foreach(var item in initial){Require(File.Exists(item.SourcePath)&&Common.Hash(item.SourcePath)==hashes[item.Id],"Removed source modified");if(item.CoverPath!=null)Require(File.Exists(item.CoverPath)&&Common.Hash(item.CoverPath)==covers[item.Id],"Removed cover modified");}
  Common.SaveNew(Path.Combine(Common.Root,"evidence/removal-smoke-passed.json"),new{initialCards=initial.Length,remainingCards=0,scope="isolated catalog only",inactiveRemovalDidNotStopDesktop=true,activeRemovalStoppedBeforeRemove=true,emptyStatePassed=true,errorPreservedEntry=true,allResourcesAndCoversRetained=true,archiveCount=Directory.GetFiles(Path.Combine(library.Data,"removed-items"),"*.json").Length,method="internal TEST_BUILD handler; not actual user click",normalPlaybackDeadline=false});Close();return;
 }catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"evidence/daily-polish-failed.json"),new{error=ex.ToString()});Write("daily-polish-failed",new{error=ex.ToString()});}await StopManaged("daily-polish-failed");Close();}
}
#endif
